mapper.select:
SELECT id, workspace_id, scope_type, scope_id, scope_name, version_id, req_id, release_id,
  seq, doc_no, tone, title, payload, content_hash, created_by, created_by_name, created_at
FROM delivery_note_snapshot WHERE id = #{id}

SELECT MAX(seq) FROM delivery_note_snapshot
WHERE workspace_id = #{workspaceId} AND version_id = #{versionId}
  AND scope_type = 'version'

SELECT id FROM delivery_note_snapshot
WHERE workspace_id = #{workspaceId} AND scope_type = #{scopeType} AND scope_id = #{scopeId}
ORDER BY id FOR UPDATE

SELECT workspace_id, snapshot_id, token, allow_download, password_hash, allowed_domains,
       watermark_text, view_count, created_at, expires_at
FROM delivery_note_share WHERE workspace_id = #{workspaceId} AND snapshot_id = #{snapshotId}

SELECT workspace_id, snapshot_id, token, allow_download, password_hash, allowed_domains,
       watermark_text, view_count, created_at, expires_at
FROM delivery_note_share WHERE token = #{token}

SELECT id, workspace_id, snapshot_id, share_token, action, ip, user_agent, referer, domain, created_at
FROM delivery_note_share_visit
WHERE workspace_id = #{workspaceId} AND snapshot_id = #{snapshotId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}
